import React, { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { Users, Plus, Trash2, Pencil, Heart, Phone } from "lucide-react";
import { toast } from "sonner";

const EMPTY = {
  name: "",
  relationship: "",
  age: "",
  gender: "",
  blood_group: "",
  medical_history: "",
  allergies: "",
  medications: "",
  vaccination_schedule: "",
  contact_number: "",
  emergency_contact_phone: "",
};

export default function Family() {
  const [items, setItems] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [editingId, setEditingId] = useState(null);
  const [busy, setBusy] = useState(false);

  const load = () => api.get("/family").then(r => setItems(r.data));
  useEffect(() => { load(); }, []);

  const set = (k, v) => setForm({ ...form, [k]: v });

  const submit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.relationship) return toast.error("Name & relationship required");
    const payload = { ...form };
    if (payload.age !== "") payload.age = Number(payload.age);
    setBusy(true);
    try {
      if (editingId) {
        await api.put(`/family/${editingId}`, payload);
        toast.success("Member updated");
      } else {
        await api.post("/family", payload);
        toast.success("Member added");
      }
      setForm(EMPTY);
      setEditingId(null);
      load();
    } catch {
      toast.error("Could not save member");
    } finally {
      setBusy(false);
    }
  };

  const startEdit = (m) => {
    setEditingId(m.id);
    setForm({
      name: m.name || "",
      relationship: m.relationship || "",
      age: m.age ?? "",
      gender: m.gender || "",
      blood_group: m.blood_group || "",
      medical_history: m.medical_history || "",
      allergies: m.allergies || "",
      medications: m.medications || "",
      vaccination_schedule: m.vaccination_schedule || "",
      contact_number: m.contact_number || "",
      emergency_contact_phone: m.emergency_contact_phone || "",
    });
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const del = async (id) => {
    await api.delete(`/family/${id}`);
    load();
    toast.success("Member removed");
  };

  const cancelEdit = () => { setEditingId(null); setForm(EMPTY); };

  return (
    <div className="max-w-5xl mx-auto" data-testid="family-page">
      <div className="glass-strong rounded-3xl p-6 flex items-center gap-3">
        <div className="w-11 h-11 rounded-2xl bg-teal-100 grid place-items-center">
          <Users className="w-5 h-5 text-teal-700" strokeWidth={2.5}/>
        </div>
        <div>
          <h1 className="font-display text-3xl">Family health</h1>
          <p className="text-sm text-slate-500">Keep track of your whole family's wellbeing.</p>
        </div>
      </div>

      <form onSubmit={submit} className="mt-6 glass rounded-3xl p-6 grid md:grid-cols-2 gap-3">
        <input data-testid="family-name" placeholder="Full name" value={form.name} onChange={(e)=>set("name", e.target.value)}
          className="md:col-span-2 px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <input data-testid="family-relationship" placeholder="Relationship (e.g. Mother)" value={form.relationship} onChange={(e)=>set("relationship", e.target.value)}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <input data-testid="family-age" type="number" placeholder="Age" value={form.age} onChange={(e)=>set("age", e.target.value)}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <input data-testid="family-gender" placeholder="Gender" value={form.gender} onChange={(e)=>set("gender", e.target.value)}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <input data-testid="family-blood" placeholder="Blood group" value={form.blood_group} onChange={(e)=>set("blood_group", e.target.value)}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <input data-testid="family-contact" placeholder="Contact number" value={form.contact_number} onChange={(e)=>set("contact_number", e.target.value)}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <input data-testid="family-emergency" placeholder="Emergency phone" value={form.emergency_contact_phone} onChange={(e)=>set("emergency_contact_phone", e.target.value)}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <textarea data-testid="family-history" placeholder="Medical history" value={form.medical_history} onChange={(e)=>set("medical_history", e.target.value)} rows={2}
          className="md:col-span-2 px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <textarea data-testid="family-allergies" placeholder="Allergies" value={form.allergies} onChange={(e)=>set("allergies", e.target.value)} rows={2}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <textarea data-testid="family-medications" placeholder="Current medications" value={form.medications} onChange={(e)=>set("medications", e.target.value)} rows={2}
          className="px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <textarea data-testid="family-vaccination" placeholder="Vaccination schedule" value={form.vaccination_schedule} onChange={(e)=>set("vaccination_schedule", e.target.value)} rows={2}
          className="md:col-span-2 px-4 py-2.5 rounded-2xl bg-white/90 border border-white outline-none text-sm"/>
        <div className="md:col-span-2 flex gap-3">
          <button data-testid="family-submit" type="submit" disabled={busy}
            className="flex-1 py-2.5 rounded-full bg-rose-400 text-white font-bold hover:scale-[1.01] transition disabled:opacity-60 inline-flex items-center justify-center gap-2">
            <Plus className="w-4 h-4"/> {editingId ? "Update member" : "Add member"}
          </button>
          {editingId && (
            <button type="button" onClick={cancelEdit}
              className="py-2.5 px-6 rounded-full bg-slate-200 text-slate-700 font-bold hover:bg-slate-300 transition">
              Cancel
            </button>
          )}
        </div>
      </form>

      <div className="mt-6 grid md:grid-cols-2 gap-4">
        {items.length === 0 && <div className="glass rounded-3xl p-6 text-slate-500 md:col-span-2">No family members yet.</div>}
        {items.map((m) => (
          <div key={m.id} className="glass rounded-3xl p-5">
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-3 min-w-0">
                <div className="w-11 h-11 rounded-2xl bg-teal-100 grid place-items-center shrink-0">
                  <Heart className="w-5 h-5 text-teal-700" strokeWidth={2.5}/>
                </div>
                <div className="min-w-0">
                  <div className="font-display text-xl truncate">{m.name}</div>
                  <div className="text-sm text-slate-500">{m.relationship}{m.age ? ` · ${m.age} yrs` : ""}</div>
                </div>
              </div>
              <div className="flex gap-2 shrink-0">
                <button onClick={() => startEdit(m)} className="p-2 rounded-xl bg-blue-100 text-blue-800 hover:bg-blue-200" data-testid={`family-edit-${m.id}`}>
                  <Pencil className="w-4 h-4"/>
                </button>
                <button onClick={() => del(m.id)} className="p-2 rounded-xl bg-red-100 text-red-700 hover:bg-red-200" data-testid={`family-del-${m.id}`}>
                  <Trash2 className="w-4 h-4"/>
                </button>
              </div>
            </div>
            <div className="mt-3 grid grid-cols-2 gap-2 text-sm">
              {m.gender && <div className="text-slate-600"><span className="text-slate-400">Gender:</span> {m.gender}</div>}
              {m.blood_group && <div className="text-slate-600"><span className="text-slate-400">Blood:</span> {m.blood_group}</div>}
              {m.contact_number && (
                <div className="col-span-2 flex items-center gap-2 text-slate-600">
                  <a href={`tel:${m.contact_number}`} className="p-1.5 rounded-lg bg-emerald-100 text-emerald-800 hover:bg-emerald-200"><Phone className="w-3.5 h-3.5"/></a>
                  {m.contact_number}
                </div>
              )}
            </div>
            {m.medical_history && <div className="mt-2 text-sm text-slate-600"><span className="text-slate-400">History:</span> {m.medical_history}</div>}
            {m.allergies && <div className="mt-1 text-sm text-slate-600"><span className="text-slate-400">Allergies:</span> {m.allergies}</div>}
            {m.medications && <div className="mt-1 text-sm text-slate-600"><span className="text-slate-400">Medications:</span> {m.medications}</div>}
            {m.vaccination_schedule && <div className="mt-1 text-sm text-slate-600"><span className="text-slate-400">Vaccinations:</span> {m.vaccination_schedule}</div>}
          </div>
        ))}
      </div>
    </div>
  );
}
